    /** Each entry explains effect, location and prerequisites, not merely its label. */
    public static function help(): array
    {
        return [
            Profile::VIEW_PUBLIC => ['Mostra a fase pública e a evolução destinada ao solicitante. Não libera números, links ou dados técnicos das WPs. Ao conceder, acrescenta também o direito nativo mínimo de leitura de acompanhamentos públicos.', 'Chamado: campo Fase Pública e aba Evolução da Demanda (nomes configuráveis).', 'Leitura nativa do chamado e entidade ativa.'],
            Profile::VIEW_TECHNICAL => ['Libera dados internos das WPs, sua coluna na listagem de chamados, monitoramento pessoal e alertas. Não autoriza criar, editar ou sincronizar WPs por si só.', 'Evolução da Demanda; coluna Work Package; Gerência > Monitoramento de Work Packages; sino de alertas.', 'Leitura do chamado quando vinculado; token pessoal para consultas ao OpenProject. Outros módulos exigem seus direitos adicionais.'],
            Profile::VIEW_HISTORY => ['Mostra os eventos de criação, conciliação, documentação e sincronização e seus detalhes técnicos.', 'Chamado > Evolução da Demanda > histórico da integração.', 'Visualizar dados técnicos do OpenProject e acesso ao chamado.'],
            Profile::CREATE_WORK_PACKAGE => ['Permite criar e vincular WPs, conciliar vínculos existentes e criar ou editar documentação com código, imagens, anexos e relações entre WPs.', 'Evolução da Demanda: Criar Work Package, Conciliar WP e Documentar.', 'Dados técnicos, leitura/alteração do chamado, entidade ativa e token pessoal com os direitos necessários no OpenProject. Conflitos exigem permissão adicional.'],
            Profile::SYNC_WORK_PACKAGE => ['Atualiza manualmente os dados das WPs vinculadas. Também permite consultar TASKs e versões; a sincronização pode aplicar as regras configuradas de fase e acompanhamento.', 'Evolução da Demanda: sincronização e TASKs e versões > Consultar agora.', 'Dados técnicos, leitura/alteração do chamado e token pessoal. Não concede administração do webhook.'],
            Profile::MANAGE_RECONCILIATION_CONFLICTS => ['Autoriza confirmar vínculos adicionais de um chamado ou WP com justificativa. Permite transferência somente nos casos seguros previstos pelo plugin; não remove históricos.', 'Conciliar Work Packages existentes: confirmação de conflitos e transferência controlada.', 'Dados técnicos, criar/vincular WPs e acesso de leitura/alteração aos chamados envolvidos.'],
            Profile::VIEW_TICKET_WP_ALERT => ['Exibe o bloco Status das WPs vinculadas, com número, status e data da última sincronização. Usa dados locais, sem consulta em tempo real e sem encerrar o chamado.', 'Painel lateral direito do formulário do chamado.', 'Dados técnicos, leitura do chamado, entidade ativa e ao menos uma WP vinculada.'],
            Profile::VIEW_TICKET_LOG => ['Apresenta o histórico nativo do chamado de forma organizada, com paginação e detalhes das alterações.', 'Aba Log do Chamado.', 'Leitura do chamado e recurso Log do Chamado habilitado na configuração global.'],
            Profile::VIEW_DASHBOARD => ['Abre os indicadores gerenciais e a grade de chamados no escopo permitido. Com dados técnicos, também permite consultar o consolidado de WPs monitoradas.', 'Gerência > Visão Gerencial de Demandas; Monitoramento > Consolidado geral.', 'Entidades ativas e leitura nativa dos chamados. Bugs e Melhorias e exportação têm direitos separados.'],
            Profile::VIEW_BUGS_DASHBOARD => ['Mostra a fila Precisam de ação, filtros de responsáveis e envelhecimento observado por etapa para bugs e melhorias.', 'Visão Gerencial de Demandas > Bugs e Melhorias.', 'Acessar a visão gerencial e visualizar dados técnicos do OpenProject.'],
            Profile::VIEW_DELIVERY_REVIEW => ['Libera conferência de entregas totais/parciais e divergências entre encerramento do chamado e WPs. Somente o status Entregue confirma entrega; não fecha chamados.', 'Bugs e Melhorias: cartões, filtros, detalhes e exportações de conferência de entregas.', 'Acesso a Bugs e Melhorias, visão gerencial e dados técnicos. Exportar também exige o direito de exportação.'],
            Profile::CONFIGURE_DASHBOARD => ['Permite salvar a visão inicial do próprio usuário. A preferência não libera abas sem autorização nem altera a escolha de colegas.', 'Visão Gerencial > Opções do painel > visão padrão.', 'Visão gerencial e os direitos da aba escolhida.'],
            Profile::EXPORT_DASHBOARD => ['Gera PDF e Excel dos indicadores e chamados filtrados e permite exportar o consolidado de WPs.', 'Botões PDF/Excel da Visão Gerencial e do Consolidado geral.', 'Visão gerencial; dados técnicos para o consolidado; direitos adicionais da aba/indicadores exportados.'],
            Profile::VIEW_BACKLOG => ['Mostra as WPs sob responsabilidade do usuário do token, agrupadas por status, com detalhes e horas pessoais.', 'Gerência > Backlog.', 'Dados técnicos e token pessoal válido. Não permite movimentar status pelo quadro.'],
            Profile::CONFIGURE_BACKLOG => ['Permite escolher e salvar as colunas de status do próprio quadro, inclusive ocultar todas. Não modifica preferências de colegas.', 'Backlog > configuração das colunas.', 'Visualizar Backlog, dados técnicos e token pessoal.'],
            Profile::VIEW_COLLEAGUE_BACKLOG => ['Permite escolher outro responsável e consultar suas WPs com o token do usuário logado. O relógio continua mostrando as horas do usuário logado.', 'Backlog > Consultar colegas, cards e painel de detalhes.', 'Visualizar Backlog e dados técnicos. O OpenProject limita os dados acessíveis ao próprio token; nunca usa o token do colega.'],
            Profile::VIEW_OPERATIONAL_HEALTH => ['Mostra chamados sem WP, tempo observado em etapas iniciais, qualidade dos dados e sincronizações desatualizadas. Permite ler evidências e histórico das tratativas, respeitando o acesso ao chamado.', 'Gerência > Pendências de Integração.', 'Dados técnicos e leitura dos chamados nas entidades ativas. Não executa verificações nem trata ocorrências.'],
            Profile::MANAGE_OPERATIONAL_HEALTH => ['Permite executar verificação, reconhecer, adiar por sete dias com motivo ou reabrir pendências. Também permite assumir o acompanhamento em seu nome, definir prazo e observação. Registra as tratativas em auditoria.', 'Pendências de Integração: Executar verificação e ações das ocorrências.', 'Visualizar pendências, dados técnicos e leitura do chamado. Não corrige nem sincroniza WPs automaticamente.'],
            Profile::PREPARE_AI_CONTEXT => ['Prepara texto selecionável de WP e, quando permitido, chamado e anexos para copiar a uma IA externa. Não envia automaticamente dados a uma IA.', 'Monitoramento de Work Packages > Preparar IA.', 'Dados técnicos, WP no monitoramento pessoal e leitura dos dados selecionados. O usuário confirma a autorização de compartilhamento.'],
            Profile::VIEW_TIME_PORTAL => ['Libera a entrada no portal de horas e ponto. Ações sobre marcações, ausências e entradas de tempo dependem dos direitos específicos.', 'Gerência > Horas e Ponto; com lançamento próprio, também Entradas de Tempo.', 'Nos direitos de horas/ponto, exceções individuais em Administração > Usuários > Horas e Ponto prevalecem sobre o perfil.'],
            Profile::LOG_OWN_TIME => ['Permite registrar e gerenciar entradas de tempo do próprio usuário e sincronizá-las com WPs. Não envia marcações de ponto ao OpenProject.', 'Gerência > Entradas de Tempo e atalho de horas na WP vinculada.', 'Portal de horas, token pessoal e permissões de horas no OpenProject; leitura do chamado quando vinculado. Exceções individuais prevalecem.'],
            Profile::LOG_OTHERS_TIME => ['Permite registrar/gerenciar entradas de tempo em nome de outro usuário, respeitando as validações da integração.', 'Entradas de Tempo: seleção do usuário do lançamento.', 'Portal de horas e lançamento próprio para abrir a tela, além dos direitos exigidos no OpenProject. Exceções individuais prevalecem.'],
            Profile::VIEW_OWN_ATTENDANCE => ['Permite consultar e registrar o próprio ponto e ausências, com conferência do banco de horas e comprovantes.', 'Horas e Ponto: calendário pessoal, Minhas ausências e auditoria do banco.', 'Acesso ao portal de horas e ponto. Exceções individuais prevalecem; não concede acesso ao ponto de colegas.'],
            Profile::VIEW_TEAM_ATTENDANCE => ['Permite consultar o ponto, ausências e auditoria de usuários vinculados às entidades ativas, respeitando associações recursivas do GLPI.', 'Horas e Ponto: consulta por usuário, lista de ausências e auditoria.', 'Portal de horas e visualizar/registrar o próprio ponto para abrir essas telas. Alterações administrativas exigem Administrar jornadas, marcações e ausências. Exceções individuais prevalecem.'],
            Profile::MANAGE_ATTENDANCE => ['Permite administrar jornadas, marcações e ausências, incluindo ajustes e saldo histórico pelos formulários do módulo.', 'Horas e Ponto e Administração > Usuários > Horas e Ponto.', 'Acesso às telas correspondentes e direitos nativos aplicáveis ao usuário. Não inclui feriados nem exceções de acesso; exceções individuais prevalecem.'],
            Profile::MANAGE_HOLIDAYS => ['Permite cadastrar e administrar feriados, compensações e dias não úteis considerados no calendário e no banco de horas.', 'Horas e Ponto > Administração do ponto.', 'Portal de horas para navegação. Exceções individuais prevalecem; não concede administração geral do plugin.'],
            Profile::MANAGE_TIME_ACCESS => ['Permite definir por usuário Herdar do perfil, Permitir ou Negar para os oito direitos de horas e ponto, incluindo administrar exceções. A decisão individual prevalece sobre o perfil; alterações registram autor e valores anterior/novo.', 'Administração do ponto e Administração > Usuários > Horas e Ponto.', 'Portal de horas e usuário-alvo vinculado às entidades ativas. O cadastro de usuários mantém os direitos nativos do GLPI. Não permite conceder exceções para configuração global, WPs ou dashboards.'],
            Profile::MANAGE_CONFIG => ['Permite administrar URLs, token automático, webhook, fases públicas, classificação, templates e parâmetros globais do plugin.', 'Configuração do plugin: Integração e automação, Classificação, Templates e Tutorial.', 'Direito do perfil ativo; token pessoal e exceções individuais não concedem esse acesso. Alterar permissões de perfis exige o direito nativo de alterar perfis.'],
        ];
    }
}
